import{K as r,a as i,c as n,b as t,k as l,q as s,ac as p}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerPoint 放映、演讲者视图与交付","description":"使用备注和演讲者视图排练，选择共享屏幕和显示器，处理字体媒体兼容，导出 PDF、讲义与视频并准备演示备份。","frontmatter":{"title":"PowerPoint 放映、演讲者视图与交付","description":"使用备注和演讲者视图排练，选择共享屏幕和显示器，处理字体媒体兼容，导出 PDF、讲义与视频并准备演示备份。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · PowerPoint 演示制作","summary":"使用备注和演讲者视图排练，选择共享屏幕和显示器，处理字体媒体兼容，导出 PDF、讲义与视频并准备演示备份。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"PowerPoint 动画、切换与媒体","link":"/tools/office/powerpoint/animation"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PowerPoint 动画、切换与媒体","link":"/tools/office/powerpoint/animation"},"next":false},"headers":[],"relativePath":"tools/office/powerpoint/present.md","filePath":"tools/office/powerpoint/present.md"}'),h={name:"tools/office/powerpoint/present.md"},k=Object.assign(h,{setup(c){const o={path:"/tools/office/powerpoint/present",app:"PowerPoint",title:"让自己看备注，让观众看幻灯片",steps:[{tab:"视图",command:"备注",setting:"本页结论；转场提示；可能问题",anchor:"walkthrough-1"},{tab:"幻灯片放映",command:"使用演讲者视图",setting:"选择显示器；检查两块屏幕",anchor:"walkthrough-2"},{tab:"文件",command:"导出",setting:"PDF 备用版；字体与媒体已检查",anchor:"walkthrough-3"}]};return(d,e)=>{const a=r("OfficeGuide");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"powerpoint-放映、演讲者视图与交付",tabindex:"-1"},[l("PowerPoint 放映、演讲者视图与交付 "),t("a",{class:"header-anchor",href:"#powerpoint-放映、演讲者视图与交付","aria-label":'Permalink to "PowerPoint 放映、演讲者视图与交付"'},"​")],-1)),e[1]||(e[1]=t("p",null,"交付前的最后一步是在接近实际场景的环境中完整演示。编辑界面没有问题，不代表投影、远程共享、媒体和备注都会按预期工作。",-1)),s(a,{guide:o}),e[2]||(e[2]=p('<h2 id="notes" tabindex="-1">写好备注并排练 <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;写好备注并排练 {#notes}&quot;">​</a></h2><p>每页备注写出开场句、解释顺序、补充例子和转场，不必把页面文字再复制一遍。需要精确说明的数据口径可以写完整，但应练到能自然解释，而不是持续低头读稿。</p><p>在“幻灯片放映”中从头或当前页开始，按实际时间排练。先测试点击次数、动画顺序、视频音量和链接，再测试跳到附录后如何回到主线。用 <code>Esc</code> 退出，放映中临时黑屏等快捷键应在目标环境提前熟悉。</p><h2 id="presenter" tabindex="-1">演讲者视图与显示器 <a class="header-anchor" href="#presenter" aria-label="Permalink to &quot;演讲者视图与显示器 {#presenter}&quot;">​</a></h2><p>演讲者视图可显示当前页、下一页、备注和时间，观众应只看到幻灯片。连接外接显示器后，在“幻灯片放映”中检查演讲者视图和监视器选择；显示在错误屏幕时可切换演讲者视图与放映画面。<a href="https://support.microsoft.com/en-us/powerpoint/training/start-the-presentation-and-see-your-notes-in-presenter-view" target="_blank" rel="noopener noreferrer">微软演讲者视图说明</a></p><p>不要只盯着自己的电脑判断成功。请从观众屏幕或远程参会者视角确认，尤其是窗口共享时，选择整个桌面可能同时暴露备注、通知和其他窗口。线上会议需要测试共享的是放映窗口、指定屏幕还是演示软件集成功能。</p><h2 id="compatibility" tabindex="-1">字体、媒体和链接 <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;字体、媒体和链接 {#compatibility}&quot;">​</a></h2><p>在目标电脑打开演示稿，检查每页标题换行、符号、公式、图表和图片。部分字体允许嵌入，部分受许可或技术限制；即使启用嵌入，也不能省略实际检查。PDF 可作为版式备用，但不会保留所有交互和动画。</p><p>视频要实际播一遍并确认声音输出设备，外部网页和文件链接要确认可访问。网络不稳定时准备离线替代说明；对核心内容，不要只留下一个需要登录的网页链接。</p><h2 id="export" tabindex="-1">选择输出 <a class="header-anchor" href="#export" aria-label="Permalink to &quot;选择输出 {#export}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输出</th><th>适合用途</th><th>检查重点</th></tr></thead><tbody><tr><td>PPTX</td><td>继续编辑或现场演示</td><td>字体、媒体、链接、备注、批注、隐藏页</td></tr><tr><td>PDF 幻灯片</td><td>稳定阅读与归档</td><td>页面顺序、字体和静态图层</td></tr><tr><td>讲义/备注页</td><td>听众记录或讲解稿</td><td>每页数量、文字可读性、备注是否适合公开</td></tr><tr><td>视频</td><td>异步培训与播放</td><td>计时、旁白、字幕和音视频同步</td></tr></tbody></table><p>导出时确认是否包含隐藏幻灯片、批注和备注；“隐藏”只是某些放映场景不自动展示，不等于内容已经从文件删除。外发副本中移除不适合公开的信息，再检查文件属性和嵌入对象。</p><h2 id="practice" tabindex="-1">现场检查与练习 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;现场检查与练习 {#practice}&quot;">​</a></h2><p>用<a href="/tools/office/powerpoint/story#outline">五页月报</a>完成一次五分钟演示。观众屏幕只能看到幻灯片，演讲者能看到自己的备注；部门数字与 Excel 月报一致，图表单位清楚。故意断开网络，再次演示核心内容，确认没有必须联网才能解释的关键环节。</p><p>交付目录至少保留可编辑稿、阅读版 PDF 和必要媒体，使用一致版本名。演示前关闭可能弹出通知的无关应用，准备可快速打开的备用文件；这些是实际演示准备，不替代内容准确性核对。</p><h2 id="walkthrough" tabindex="-1">图示跟做：让自己看备注，让观众看幻灯片 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：让自己看备注，让观众看幻灯片 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：把提示写在备注区 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：把提示写在备注区 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：视图 → 备注。</strong></p><p>打开备注区，为每页写一句结论、一个补充例子和转场提示。备注用于提醒讲述者，不应塞满逐字稿。用普通视图核对哪些文字放在幻灯片上、哪些只在备注里，防止把本应私下提示的内容放到观众画面。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：接入设备后分别检查屏幕 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：接入设备后分别检查屏幕 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：幻灯片放映 → 使用演讲者视图。</strong></p><p>连接投影或第二屏，在操作系统显示设置中选择适当的扩展方式，再在 PowerPoint 的幻灯片放映选项卡启用演讲者视图。实际开始放映，站在观众屏幕前确认只显示幻灯片，自己的屏幕才有备注、下一页和计时。不要仅凭勾选框判断配置正确。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：准备失效时可继续展示的材料 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：准备失效时可继续展示的材料 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>检查视频、音频、字体与外部链接，在演示电脑上重新打开并播放一遍。导出 PDF 作为静态备用，并保留可编辑演示文件。线上会议要核对共享的是幻灯片窗口还是整个桌面，避免将演讲者备注或其他应用一起共享。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>两块屏幕内容反了时，检查演讲者视图中的显示器交换选项及系统屏幕设置。遇到临场故障先切到可用的静态版本，避免在观众面前反复修改整份演示稿。</p><p>图示操作参考：<a href="https://support.microsoft.com/zh-cn/powerpoint/training/use-presenter-view-in-powerpoint" target="_blank" rel="noopener noreferrer">微软官方：使用演讲者视图</a>。核对日期：2026-11-02；界面示意与练习案例为本站独立编写。</p>',29))])}}});export{u as __pageData,k as default};
